import calendar
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

_CENT = Decimal('0.01')
_ZERO = Decimal('0.00')
_ONE = Decimal('1')


def amortize(principal: str, annual_rate_percent: str, months: int, start_date: str) -> list[dict]:
    if not isinstance(principal, str):
        raise ValueError('principal must be a string')
    try:
        principal_value = Decimal(principal)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('principal must be a valid decimal') from None
    if not principal_value.is_finite() or principal_value <= 0:
        raise ValueError('principal must be finite and positive')
    if principal_value.as_tuple().exponent < -2:
        raise ValueError('principal must have at most 2 decimal places')
    if not isinstance(annual_rate_percent, str):
        raise ValueError('annual_rate_percent must be a string')
    try:
        rate_value = Decimal(annual_rate_percent)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('annual_rate_percent must be a valid decimal') from None
    if not rate_value.is_finite() or rate_value < 0 or rate_value > 100:
        raise ValueError('annual_rate_percent must be between 0 and 100')
    if isinstance(months, bool) or not isinstance(months, int):
        raise ValueError('months must be an integer')
    if months < 1 or months > 360:
        raise ValueError('months must be between 1 and 360')
    if not isinstance(start_date, str):
        raise ValueError('start_date must be a string')
    if len(start_date) != 10 or start_date[4] != '-' or start_date[7] != '-':
        raise ValueError('start_date must be YYYY-MM-DD')
    year_part = start_date[0:4]
    month_part = start_date[5:7]
    day_part = start_date[8:10]
    if not (year_part.isascii() and year_part.isdigit() and month_part.isascii() and month_part.isdigit() and day_part.isascii() and day_part.isdigit()):
        raise ValueError('start_date must be YYYY-MM-DD')
    try:
        start_day = date(int(year_part), int(month_part), int(day_part))
    except ValueError:
        raise ValueError('start_date must be a valid calendar date') from None
    with localcontext() as ctx:
        ctx.prec = 50
        monthly_rate = rate_value / Decimal('1200')
        opening_principal = principal_value.quantize(_CENT, rounding=ROUND_HALF_UP)
        if monthly_rate > 0:
            level_payment = (opening_principal * monthly_rate / (_ONE - (_ONE + monthly_rate) ** (-months))).quantize(_CENT, rounding=ROUND_HALF_UP)
        else:
            level_payment = (opening_principal / months).quantize(_CENT, rounding=ROUND_HALF_UP)
        schedule = []
        balance = opening_principal
        anchor_day = start_day.day
        for n in range(1, months + 1):
            interest = (balance * monthly_rate).quantize(_CENT, rounding=ROUND_HALF_UP)
            if n < months:
                payment = level_payment
                principal_part = (payment - interest).quantize(_CENT, rounding=ROUND_HALF_UP)
                new_balance = (balance - principal_part).quantize(_CENT, rounding=ROUND_HALF_UP)
            else:
                principal_part = balance
                payment = (balance + interest).quantize(_CENT, rounding=ROUND_HALF_UP)
                new_balance = _ZERO
            month_offset = (start_day.month - 1) + n
            target_year = start_day.year + month_offset // 12
            target_month = month_offset % 12 + 1
            last_day = calendar.monthrange(target_year, target_month)[1]
            target_day = anchor_day if anchor_day <= last_day else last_day
            payment_date = f'{target_year:04d}-{target_month:02d}-{target_day:02d}'
            schedule.append({'n': n, 'date': payment_date, 'payment': payment, 'interest': interest, 'principal': principal_part, 'balance': new_balance})
            balance = new_balance
        return schedule


def total_interest(schedule) -> Decimal:
    with localcontext() as ctx:
        ctx.prec = 50
        total = _ZERO
        for row in schedule:
            total = total + row['interest']
        return total.quantize(_CENT, rounding=ROUND_HALF_UP)
